package ru.truetv.launcher;
import java.io.*;
import java.net.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.interfaces.*;
import java.math.BigInteger;
import java.util.*;

/** Legacy ADB AUTH/shell only. One explicit target, one bounded channel at a time. */
public final class AdbWire implements AutoCloseable {
 private final Socket socket=new Socket();private InputStream input;private OutputStream output;private int local=0;private long deadline;
 private static final int CNXN=word("CNXN"),AUTH=word("AUTH"),OPEN=word("OPEN"),OKAY=word("OKAY"),WRTE=word("WRTE"),CLSE=word("CLSE");
 static int word(String s){return s.charAt(0)|s.charAt(1)<<8|s.charAt(2)<<16|s.charAt(3)<<24;}
 private static final class Packet {int kind,a,b;byte[] data;}
 public AdbWire(String address,KeyPair keys)throws Exception {try{String[] endpoint=endpoint(address);socket.connect(new InetSocketAddress(endpoint[0],Integer.parseInt(endpoint[1])),5000);socket.setSoTimeout(1500);input=socket.getInputStream();output=socket.getOutputStream();deadline=System.nanoTime()+45000000000L;send(CNXN,0x01000000,4096,"host::\0".getBytes(StandardCharsets.UTF_8));boolean signed=false,offered=false;for(;;){Packet p=read();if(p.kind==CNXN)break;if(p.kind!=AUTH||p.a!=1||p.data.length!=20)throw new IOException("Unsupported ADB authentication (legacy RSA required)");if(!signed){Signature signer=Signature.getInstance("NONEwithRSA");signer.initSign(keys.getPrivate());signer.update(new byte[]{0x30,0x21,0x30,0x09,0x06,0x05,0x2b,0x0e,0x03,0x02,0x1a,0x05,0x00,0x04,0x14});signer.update(p.data);send(AUTH,2,0,signer.sign());signed=true;}else if(!offered){send(AUTH,3,0,(base64(publicKey((RSAPublicKey)keys.getPublic()))+" truetv@launcher\0").getBytes(StandardCharsets.UTF_8));offered=true;}else throw new IOException("ADB authorization rejected");}}catch(Exception e){socket.close();throw e;}}
 public static String[] endpoint(String text){String value=text==null?"":text.trim();String host,port;if(value.startsWith("[")){int at=value.indexOf("]:");if(at<2)throw new IllegalArgumentException("Use [IPv6]:port");host=value.substring(1,at);port=value.substring(at+2);}else{int at=value.lastIndexOf(':');if(at<1||value.indexOf(':')!=at)throw new IllegalArgumentException("Use address:port");host=value.substring(0,at);port=value.substring(at+1);}int n=Integer.parseInt(port);if(n<1||n>65535||host.length()>253||!host.matches("[A-Za-z0-9_.:%-]+"))throw new IllegalArgumentException("Invalid address:port");return new String[]{host,String.valueOf(n)};}
 public synchronized ShellReply shell(String command)throws Exception {try{return shellChannel(command);}catch(IOException failed){try{close();}catch(IOException ignored){}throw failed;}}
 private ShellReply shellChannel(String command)throws Exception {String marker="__TRUE_TV_"+UUID.randomUUID().toString().replace("-","")+"__";String wrapped=command+"; _true_tv_status=$?; printf '\\n"+marker+"%s\\n' \"$_true_tv_status\"";deadline=System.nanoTime()+45000000000L;int id=++local,remote=0,ignored=0;ByteArrayOutputStream collected=new ByteArrayOutputStream();send(OPEN,id,0,("shell:"+wrapped+"\0").getBytes(StandardCharsets.UTF_8));for(;;){Packet p=read();if(p.b!=id){if(p.b>0&&p.b<id&&p.data.length==0&&(p.kind==CLSE||p.kind==OKAY)){if(++ignored>16)throw new IOException("Too many stale ADB control frames");continue;}throw new IOException("Unexpected ADB channel: kind="+p.kind+", recipient="+p.b+", active="+id);}if(remote==0)remote=p.a;if(p.kind==OKAY)continue;if(p.kind==WRTE){if(collected.size()+p.data.length>65536)throw new IOException("ADB output limit");collected.write(p.data);send(OKAY,id,remote,new byte[0]);}else if(p.kind==CLSE){send(CLSE,id,remote,new byte[0]);break;}else throw new IOException("Unexpected ADB packet");}String text=new String(collected.toByteArray(),StandardCharsets.UTF_8);int at=text.lastIndexOf(marker);if(at<0)throw new IOException("ADB command result not confirmed");int code;try{code=Integer.parseInt(text.substring(at+marker.length()).trim());}catch(NumberFormatException e){throw new IOException("Invalid ADB exit status");}return new ShellReply(code,text.substring(0,at).trim());}
 private void send(int kind,int a,int b,byte[] data)throws IOException {int sum=0;for(byte value:data)sum+=value&255;ByteBuffer head=ByteBuffer.allocate(24).order(ByteOrder.LITTLE_ENDIAN);head.putInt(kind).putInt(a).putInt(b).putInt(data.length).putInt(sum).putInt(~kind);output.write(head.array());output.write(data);output.flush();}
 private byte[] exact(int length)throws IOException {byte[] bytes=new byte[length];int at=0;while(at<length){if(System.nanoTime()>deadline)throw new SocketTimeoutException("ADB timeout");try{int n=input.read(bytes,at,length-at);if(n<0)throw new EOFException("ADB connection closed");at+=n;}catch(SocketTimeoutException wait){if(System.nanoTime()>deadline)throw wait;}}return bytes;}
 private Packet read()throws IOException {ByteBuffer head=ByteBuffer.wrap(exact(24)).order(ByteOrder.LITTLE_ENDIAN);Packet p=new Packet();p.kind=head.getInt();p.a=head.getInt();p.b=head.getInt();int len=head.getInt(),checksum=head.getInt(),magic=head.getInt();if(len<0||len>1048576||magic!=~p.kind)throw new IOException("Invalid ADB frame");p.data=exact(len);int actual=0;for(byte value:p.data)actual+=value&255;if(actual!=checksum)throw new IOException("ADB checksum mismatch");return p;}
 public static byte[] publicKey(RSAPublicKey key){if(key.getModulus().bitLength()>2048)throw new IllegalArgumentException("ADB requires RSA2048");BigInteger n=key.getModulus(),base=BigInteger.ONE.shiftLeft(32);ByteBuffer b=ByteBuffer.allocate(524).order(ByteOrder.LITTLE_ENDIAN);b.putInt(64).putInt(n.mod(base).modInverse(base).negate().mod(base).intValue());little(b,n,256);little(b,BigInteger.ONE.shiftLeft(4096).mod(n),256);b.putInt(key.getPublicExponent().intValue());return b.array();}
 private static void little(ByteBuffer b,BigInteger n,int count){for(int i=0;i<count;i++){b.put(n.byteValue());n=n.shiftRight(8);}}
 private static String base64(byte[] bytes){String alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";StringBuilder s=new StringBuilder();for(int i=0;i<bytes.length;i+=3){int a=bytes[i]&255,b=i+1<bytes.length?bytes[i+1]&255:0,c=i+2<bytes.length?bytes[i+2]&255:0;s.append(alphabet.charAt(a>>>2)).append(alphabet.charAt((a&3)<<4|b>>>4)).append(i+1<bytes.length?alphabet.charAt((b&15)<<2|c>>>6):'=').append(i+2<bytes.length?alphabet.charAt(c&63):'=');}return s.toString();}
 public void close()throws IOException {socket.close();}
}
